import { L, type JourneyInteractiveSection } from "./genesis-interactive";
import type { BibleRef } from "./references";

/**
 * Camada interativa de Levítico: paradas, quiz, família e tempo por movimento.
 * O livro inteiro acontece no Sinai (Lv 1:1; 25:1; 27:34): não há deslocamentos.
 * As paradas com lugar usam "sinai" (places.ts) com título próprio; as outras são só de texto.
 * Pessoas: todas já estão em journeyPeople (moses, aaron, god, nadab, abihu, eleazar, ithamar).
 *
 * ESTADO: PENDENTE DE REVISÃO HUMANA. Textos escritos para a Jornada a partir do texto
 * bíblico citado em cada `ref`; ainda não passaram por revisão teológica nem de tradução.
 * O português (chave pt-PT, que também serve o pt-BR) está na norma brasileira.
 * Referências: só trechos com a mesma numeração nas Bíblias dos 6 idiomas (evita Lv 6:1–7,
 * que nas Bíblias alemãs é 5:20–26).
 * Datas: cronologia tradicional (saída do Egito c. 1446 a.C.; tabernáculo erguido no 1.º mês
 * do 2.º ano, Êx 40:17), todas aproximadas.
 */
export const leviticusReviewStatus = "pendente-revisao-humana" as const;

const lv = (chapter: number, verse?: number, endVerse?: number, endChapter?: number): BibleRef =>
  ({ book: "leviticus", chapter, verse, endVerse, endChapter });

